/**
 * Writes src/cpp/generated/format.h from src/ts/format.ts, so that the C++
 * player and the TypeScript builder cannot disagree on an opcode or an offset.
 */
import fs from "fs";
import path from "path";

import { MAGIC, Op, RESERVED_WORDS, VERSION, tables } from "../src/ts/format";

import { PackageRoot } from "./skia";

const Output = path.join(PackageRoot, "src", "cpp", "generated", "format.h");

export const generateFormat = () => {
  const lines = [
    "// Generated by scripts/generate-format.ts from src/ts/format.ts.",
    "// Do not edit: change format.ts and run `yarn generate-format`.",
    "#pragma once",
    "",
    "#include <cstdint>",
    "",
    "namespace skwasm::format {",
    "",
    `constexpr uint32_t kMagic = 0x${MAGIC.toString(16)};`,
    `constexpr uint32_t kVersion = ${VERSION};`,
    `constexpr uint32_t kReservedWords = ${RESERVED_WORDS};`,
    "",
    "enum class Op : uint16_t {",
    ...Object.entries(Op).map(([name, value]) => `  k${name} = ${value},`),
    "};",
  ];
  for (const [table, entries] of Object.entries(tables)) {
    lines.push("");
    for (const [name, value] of Object.entries(entries)) {
      lines.push(`constexpr uint32_t k${table}${name} = ${value};`);
    }
  }
  lines.push("", "}  // namespace skwasm::format", "");
  const header = lines.join("\n");
  fs.mkdirSync(path.dirname(Output), { recursive: true });
  // Left alone when up to date, so that it does not look modified to a build.
  if (!fs.existsSync(Output) || fs.readFileSync(Output, "utf8") !== header) {
    fs.writeFileSync(Output, header);
  }
  return Output;
};

if (require.main === module) {
  console.log(`✅ ${path.relative(PackageRoot, generateFormat())}`);
}
